style.css:
@-moz-document domain("instagram.com") {
body {
        background-color: #FFE6F6 !important; /* soft pastel pink */
    }
    header, nav, .x1iyjqo2, .x9f619, .x1n2onr6 {
        background-color: #FFDDEE !important; /* navbar & header */
    }
    section, .x78zum5, .x6s0dn4, .x1q0g3np, .x1pi30zi {
        background-color: #FFE6F6 !important; /* main content */
    }
    ._aa4b, ._ab1y, .x1yztbdb {
        background-color: #FFF0F8 !important; /* post backgrounds */
        border-radius: 10px;
    }
    * {
        color: #FF66A3 !important; /* pink text */
    }
    a {
        color: #FF3385 !important; /* pink links */
    }
    input, textarea {
        background-color: #FFF0F8 !important; /* soft pink input fields */
        border: 1px solid #FF99CC !important;
        color: #FF3385 !important;
    }
    button, ._acan {
        background-color: #FF99CC !important; /* pink buttons */
        color: white !important;
        border-radius: 5px;
        padding: 5px 10px;
    }
    button:hover, ._acan:hover {
        background-color: #FF66A3 !important;
    }
}
